using Financeiro.Application;
using Financeiro.Domain;
using Financeiro.Infrastructure;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.RateLimiting;
using Microsoft.EntityFrameworkCore;

namespace Financeiro.Api.Controllers;

[ApiController, Authorize, EnableRateLimiting("expensive"), Route("api/v1/dashboard")]
public sealed class DashboardController(FinanceiroDbContext db) : ControllerBase
{
    [HttpGet] public async Task<IActionResult> Get(int? month,int? year,CancellationToken ct){var now=DateTime.UtcNow;var m=month??now.Month;var y=year??now.Year;var start=new DateOnly(y,m,1);var end=start.AddMonths(1);var tx=await db.Transactions.AsNoTracking().Include(x=>x.Category).Where(x=>x.Date>=start&&x.Date<end).ToListAsync(ct);var accounts=await db.Accounts.AsNoTracking().Include(x=>x.Transactions).ToListAsync(ct);var income=tx.Where(x=>x.Type==TransactionType.Income&&x.Status!=TransactionStatus.Cancelled).Sum(x=>x.Amount);var expense=tx.Where(x=>x.Type==TransactionType.Expense&&x.Status!=TransactionStatus.Cancelled).Sum(x=>x.Amount);var byCategory=tx.Where(x=>x.Type==TransactionType.Expense).GroupBy(x=>x.Category?.Name??"Outros").Select(g=>new{category=g.Key,value=g.Sum(x=>x.Amount)}).Cast<object>().ToArray();var cashRows=await db.Transactions.AsNoTracking().Where(x=>x.Date>=start.AddMonths(-5)&&x.Date<end).GroupBy(x=>new{x.Date.Year,x.Date.Month}).Select(g=>new{year=g.Key.Year,month=g.Key.Month,income=g.Where(x=>x.Type==TransactionType.Income).Sum(x=>x.Amount),expense=g.Where(x=>x.Type==TransactionType.Expense).Sum(x=>x.Amount)}).OrderBy(x=>x.year).ThenBy(x=>x.month).ToListAsync(ct);var cash=cashRows.Select(x=>new{month=$"{x.month:D2}/{x.year}",x.income,x.expense}).Cast<object>().ToArray();return Ok(new DashboardResponse(accounts.Sum(x=>x.InitialBalance+x.Transactions.Where(t=>t.Status==TransactionStatus.Paid).Sum(t=>t.Type==TransactionType.Income?t.Amount:-t.Amount)),accounts.Sum(x=>x.InitialBalance+x.Transactions.Where(t=>t.Status==TransactionStatus.Paid).Sum(t=>t.Type==TransactionType.Income?t.Amount:-t.Amount))+await db.Investments.SumAsync(x=>x.Quantity*x.CurrentPrice,ct)-await db.Debts.SelectMany(x=>x.Installments).Where(x=>x.PaidAt==null).SumAsync(x=>x.Amount,ct),income,expense,income-expense,await db.Investments.SumAsync(x=>x.Quantity*x.CurrentPrice,ct),await db.Debts.SelectMany(x=>x.Installments).Where(x=>x.PaidAt==null).SumAsync(x=>x.Amount,ct),await db.CreditCards.SumAsync(x=>x.Limit,ct),await db.Transactions.CountAsync(x=>x.Status==TransactionStatus.Pending&&x.Type==TransactionType.Expense,ct),await db.Transactions.CountAsync(x=>x.Status==TransactionStatus.Pending&&x.Type==TransactionType.Income,ct),cash,byCategory,tx.OrderByDescending(x=>x.Date).Take(8).Cast<object>().ToArray(),tx.Where(x=>x.DueDate>=DateOnly.FromDateTime(now)&&x.DueDate<=DateOnly.FromDateTime(now.AddDays(30))).OrderBy(x=>x.DueDate).Cast<object>().ToArray()));}
}

[ApiController,Authorize,Route("api/v1/budgets")]
public sealed class BudgetsController(FinanceiroDbContext db,ICurrentUser current):ControllerBase
{
 [HttpGet]public async Task<IActionResult>List(int? month,int? year,CancellationToken ct){var n=DateTime.UtcNow;var m=month??n.Month;var y=year??n.Year;var start=new DateOnly(y,m,1);var end=start.AddMonths(1);var b=await db.Budgets.AsNoTracking().Include(x=>x.Category).Where(x=>x.Month==m&&x.Year==y).ToListAsync(ct);var spent=await db.Transactions.AsNoTracking().Where(x=>x.Date>=start&&x.Date<end&&x.Type==TransactionType.Expense&&x.Status!=TransactionStatus.Cancelled).GroupBy(x=>x.CategoryId).Select(g=>new{CategoryId=g.Key!.Value,value=g.Sum(x=>x.Amount)}).ToDictionaryAsync(x=>x.CategoryId,x=>x.value,ct);return Ok(b.Select(x=>new{x.Id,x.CategoryId,Category=x.Category!.Name,x.Month,x.Year,x.Amount,Spent=spent.GetValueOrDefault(x.CategoryId),Available=x.Amount-spent.GetValueOrDefault(x.CategoryId),Percent=x.Amount==0?0:spent.GetValueOrDefault(x.CategoryId)/x.Amount*100}));}
 [HttpPost]public async Task<IActionResult>Create(BudgetRequest r,CancellationToken ct){if(r.Amount<=0||r.Month is<1 or>12||r.Year is<2000 or>2200||!await db.Categories.AnyAsync(x=>x.Id==r.CategoryId&&x.Type==TransactionType.Expense&&x.IsActive,ct))return BadRequest("Orçamento inválido.");if(await db.Budgets.AnyAsync(x=>x.CategoryId==r.CategoryId&&x.Month==r.Month&&x.Year==r.Year,ct))return Conflict("Já existe um orçamento para esta categoria e período.");var x=new Budget{UserId=current.UserId,CategoryId=r.CategoryId,Month=r.Month,Year=r.Year,Amount=r.Amount};db.Add(x);await db.SaveChangesAsync(ct);return Ok(x);}
 [HttpPut("{id:guid}")]public async Task<IActionResult>Update(Guid id,BudgetRequest r,CancellationToken ct){var x=await db.Budgets.FindAsync([id],ct);if(x is null)return NotFound();if(r.Amount<=0||r.Month is<1 or>12||r.Year is<2000 or>2200||!await db.Categories.AnyAsync(c=>c.Id==r.CategoryId&&c.Type==TransactionType.Expense&&c.IsActive,ct))return BadRequest("Orçamento inválido.");if(await db.Budgets.AnyAsync(b=>b.Id!=id&&b.CategoryId==r.CategoryId&&b.Month==r.Month&&b.Year==r.Year,ct))return Conflict("Já existe um orçamento para esta categoria e período.");x.CategoryId=r.CategoryId;x.Month=r.Month;x.Year=r.Year;x.Amount=r.Amount;await db.SaveChangesAsync(ct);return Ok(x);}
 [HttpDelete("{id:guid}")]public async Task<IActionResult>Delete(Guid id,CancellationToken ct){var x=await db.Budgets.FindAsync([id],ct);if(x is null)return NotFound();db.Remove(x);await db.SaveChangesAsync(ct);return NoContent();}
}

[ApiController,Authorize,Route("api/v1/goals")]
public sealed class GoalsController(FinanceiroDbContext db,ICurrentUser current):ControllerBase
{
 [HttpGet]public async Task<IActionResult>List(CancellationToken ct)=>Ok(await db.FinancialGoals.AsNoTracking().Include(x=>x.Contributions).Select(x=>new{x.Id,x.Name,x.TargetAmount,x.Deadline,x.Color,x.IsCompleted,CurrentAmount=x.Contributions.Sum(c=>c.Amount),Percent=x.TargetAmount<=0?0:Math.Min(100,x.Contributions.Sum(c=>c.Amount)/x.TargetAmount*100)}).ToListAsync(ct));
 [HttpPost]public async Task<IActionResult>Create(GoalRequest r,CancellationToken ct){if(string.IsNullOrWhiteSpace(r.Name)||r.Name.Trim().Length>160||r.TargetAmount<=0)return BadRequest("Meta inválida.");if(r.Deadline is not null&&r.Deadline<DateOnly.FromDateTime(DateTime.UtcNow))return BadRequest("A data alvo não pode estar no passado.");var x=new FinancialGoal{UserId=current.UserId,Name=r.Name.Trim(),TargetAmount=r.TargetAmount,Deadline=r.Deadline,Color=r.Color??"#10B981"};db.Add(x);await db.SaveChangesAsync(ct);return Ok(x);}
 [HttpPut("{id:guid}")]public async Task<IActionResult>Update(Guid id,GoalRequest r,CancellationToken ct){var x=await db.FinancialGoals.FindAsync([id],ct);if(x is null)return NotFound();if(string.IsNullOrWhiteSpace(r.Name)||r.Name.Trim().Length>160||r.TargetAmount<=0)return BadRequest("Meta inválida.");x.Name=r.Name.Trim();x.TargetAmount=r.TargetAmount;x.Deadline=r.Deadline;x.Color=r.Color??x.Color;x.IsCompleted=x.CurrentAmount>=x.TargetAmount;await db.SaveChangesAsync(ct);return Ok(x);}
 [HttpPost("{id:guid}/contributions")]public async Task<IActionResult>Contribute(Guid id,ContributionRequest r,CancellationToken ct){if(r.Amount<=0)return BadRequest("Valor deve ser positivo.");var goal=await db.FinancialGoals.Include(x=>x.Contributions).SingleOrDefaultAsync(x=>x.Id==id,ct);if(goal is null)return NotFound();var x=new GoalContribution{UserId=current.UserId,FinancialGoalId=id,Amount=r.Amount,Date=r.Date,Notes=r.Notes};goal.IsCompleted=goal.CurrentAmount+r.Amount>=goal.TargetAmount;db.Add(x);await db.SaveChangesAsync(ct);return Ok(x);}
 [HttpDelete("{id:guid}")]public async Task<IActionResult>Delete(Guid id,CancellationToken ct){var x=await db.FinancialGoals.FindAsync([id],ct);if(x is null)return NotFound();db.Remove(x);await db.SaveChangesAsync(ct);return NoContent();}
}

[ApiController,Authorize,Route("api/v1/investments")]
public sealed class InvestmentsController(FinanceiroDbContext db,ICurrentUser current):ControllerBase
{
 [HttpGet]public async Task<IActionResult>List(CancellationToken ct)=>Ok(await db.Investments.AsNoTracking().Select(x=>new{x.Id,x.Asset,x.Type,x.Quantity,x.AveragePrice,x.CurrentPrice,x.Broker,InvestedAmount=x.Quantity*x.AveragePrice,CurrentAmount=x.Quantity*x.CurrentPrice,ReturnPercent=x.Quantity*x.AveragePrice==0?0:(x.CurrentPrice/x.AveragePrice-1)*100}).ToListAsync(ct));
 [HttpPost]public async Task<IActionResult>Create(InvestmentRequest r,CancellationToken ct){if(string.IsNullOrWhiteSpace(r.Asset)||r.Asset.Trim().Length>120||r.Quantity<0||r.AveragePrice<0||r.CurrentPrice<0)return BadRequest("Investimento inválido.");var x=new Investment{UserId=current.UserId,Asset=r.Asset.Trim(),Type=r.Type,Quantity=r.Quantity,AveragePrice=r.AveragePrice,CurrentPrice=r.CurrentPrice,Broker=string.IsNullOrWhiteSpace(r.Broker)?null:r.Broker.Trim()};db.Add(x);await db.SaveChangesAsync(ct);return Ok(x);}
 [HttpPut("{id:guid}")]public async Task<IActionResult>Update(Guid id,InvestmentRequest r,CancellationToken ct){var x=await db.Investments.FindAsync([id],ct);if(x is null)return NotFound();if(string.IsNullOrWhiteSpace(r.Asset)||r.Asset.Trim().Length>120||r.Quantity<0||r.AveragePrice<0||r.CurrentPrice<0)return BadRequest("Investimento inválido.");x.Asset=r.Asset.Trim();x.Type=r.Type;x.Quantity=r.Quantity;x.AveragePrice=r.AveragePrice;x.CurrentPrice=r.CurrentPrice;x.Broker=string.IsNullOrWhiteSpace(r.Broker)?null:r.Broker.Trim();await db.SaveChangesAsync(ct);return Ok(x);}
 [HttpDelete("{id:guid}")]public async Task<IActionResult>Delete(Guid id,CancellationToken ct){var x=await db.Investments.FindAsync([id],ct);if(x is null)return NotFound();db.Remove(x);await db.SaveChangesAsync(ct);return NoContent();}
}
